#include "cusums.h"

void CumulativeSums(int *res_sup, int *res_inf, int epsilon[N]) {
    int S = 0;
    int sup = S;
    int inf = S;

    for (int k = 0; k < N; k++) {
        if (epsilon[k] == 1) {
            S += 1;
        } else {
            S -= 1;
        }

        if (S > sup) {
            sup = S;
        }
        if (S < inf) {
            inf = S;
        }
    }

    *res_sup = sup;
    *res_inf = inf;
}
